import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ storage: multer.memoryStorage() });
const router = express.Router();

interface ScanRequestBody {
  jobDescription: string;
}

router.post('/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume PDF uploaded.' });
      return;
    }

    const { jobDescription } = req.body as ScanRequestBody;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required.' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Simple keyword extraction & matching logic
    const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'an', 'this']);
    const jdWords = jobDescription
      .toLowerCase()
      .replace(/[^\w\s]/gi, '')
      .split(/\s+/
      .filter(word => word.length > 2 && !stopWords.has(word));

    const uniqueKeywords = Array.from(new Set(jdWords));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    uniqueKeywords.forEach(keyword => {
      if (resumeText.includes(keyword)) {
        matchedKeywords.push(keyword);
      } else {
        missingKeywords.push(keyword);
      }
    });

    const matchScore = Math.round((matchedKeywords.length / (uniqueKeywords.length || 1)) * 100);

    res.json({
      matchScore,
      breakdown: {
        matched: matchedKeywords,
        missing: missingKeywords,
        totalChecked: uniqueKeywords.length
      }
    });
  } catch (error) {
    console.error('Error processing resume:', error);
    res.status(500).json({ error: 'Internal server error while parsing PDF.' });
  }
});

export default router;

import React, { useState } from 'react';

interface ScanResult {
  matchScore: number;
  breakdown: {
    matched: string[];
    missing: string[];
    totalChecked: number;
  };
}

export const TailwindAnimatedMatchCard: React.FC = () => {
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ScanResult | null>(null);

  const handleSimulatedScan = () => {
    setLoading(true);
    setTimeout(() => {
      setResult({
        matchScore: 78,
        breakdown: {
          matched: ['react', 'typescript', 'tailwind', 'nodejs', 'express'],
          missing: ['graphql', 'docker', 'kubernetes', 'aws'],
          totalChecked: 9
        }
      });
      setLoading(false);
    }, 1000);
  };

  return (
    <div className="max-w-xl mx-auto p-6 bg-white rounded-xl shadow-lg border border-gray-100">
      <h2 className="text-2xl font-bold text-gray-800 mb-4">Resume Keyword Matcher</h2>

      <button
        onClick={handleSimulatedScan}
        disabled={loading}
        className="w-full py-2 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition-colors duration-200 disabled:opacity-50"
      >
        {loading ? 'Analyzing Resume...' : 'Run Quick Scan'}
      </button>

      {result && (
        <div className="mt-6 space-y-6">
          <div>
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-semibold text-gray-700">Overall Match Score</span>
              <span className="text-lg font-bold text-indigo-600">{result.matchScore}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
              <div
                className="bg-indigo-600 h-3 rounded-full transition-all duration-1000 ease-out"
                style={{ width: `${result.matchScore}%` }}
              />
            </div>
          </div>

          <div>
            <h3 className="text-sm font-semibold text-green-700 mb-2">Matched Keywords</h3>
            <div className="flex flex-wrap gap-2">
              {result.breakdown.matched.map((kw) => (
                <span key={kw} className="px-3 py-1 bg-green-50 text-green-700 border border-green-200 text-xs font-medium rounded-full">
                  {kw}
                </span>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-sm font-semibold text-red-700 mb-2">Missing Keywords</h3>
            <div className="flex flex-wrap gap-2">
              {result.breakdown.missing.map((kw) => (
                <span key={kw} className="px-3 py-1 bg-red-50 text-red-700 border border-red-200 text-xs font-medium rounded-full">
                  {kw}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
